import csv
import io
import re


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str) or not raw_csv:
        return {"columns": [], "rows": []}

    try:
        csv.field_size_limit(max(131072, len(raw_csv) + 1))
    except (OverflowError, ValueError):
        try:
            csv.field_size_limit(2147483647)
        except (OverflowError, ValueError):
            pass

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )

    records = []
    try:
        records = [list(record) for record in reader]
    except csv.Error:
        records = []

    if not records:
        return {"columns": [], "rows": []}

    if records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    expected_width = 9

    def header_score(record, index):
        if not record:
            return -1000000

        nonempty = [value.strip() for value in record if value.strip()]
        score = len(nonempty) * 20

        if len(record) == expected_width:
            score += 60
        else:
            score -= abs(len(record) - expected_width) * 12

        if len(nonempty) == len(record):
            score += 15

        lowered = [value.casefold() for value in nonempty]
        if len(set(lowered)) == len(lowered):
            score += 10

        if nonempty and all(len(value) <= 80 for value in nonempty):
            score += 10

        for value in nonempty:
            text = value.strip()
            if re.fullmatch(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)", text):
                score -= 35
            elif re.fullmatch(r"[$€£¥]\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)", text):
                score -= 35
            elif re.fullmatch(r"\d{1,4}[-/]\d{1,2}[-/]\d{1,4}", text):
                score -= 35
            elif re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?", text):
                score -= 35
            elif re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", text):
                score -= 35

        following = records[index + 1:index + 4]
        score += sum(8 for row in following if len(row) == expected_width)
        return score

    search_limit = min(len(records), 30)
    candidates = [i for i in range(search_limit) if records[i]]
    if not candidates:
        return {"columns": [], "rows": []}

    header_index = max(candidates, key=lambda i: (header_score(records[i], i), -i))

    def normalize(record):
        values = [str(value) for value in record]
        if len(values) < expected_width:
            return values + [""] * (expected_width - len(values))
        if len(values) > expected_width:
            return values[:expected_width - 1] + [
                ",".join(values[expected_width - 1:])
            ]
        return values

    columns = normalize(records[header_index])
    rows = [normalize(record) for record in records[header_index + 1:]]

    return {"columns": columns, "rows": rows}
